#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    vector<int> v;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        v.push_back(x);
    }

    int total = 0;
    for (auto it = v.begin(); it != v.end(); ++it) {
        total += *it;
    }
    cout << total << endl;
    return 0;
}
